#!/usr/bin/env bash
# ============================================================================
# VideoMind rebuild, Part 3a: uploads that survive, and play at once
# ============================================================================
# FOR THE rebuild BRANCH ONLY. It refuses to run on main.
#
# Until now a video went from the browser to Shelby first, in one piece,
# and only then to the server. A dropped connection meant starting over,
# a Shelby outage meant no upload at all, and nothing could be watched
# until every step had passed.
#
# After this part:
#   * the browser sends the file straight to storage (the R2 bucket) in
#     parts of 8 MB. The server only hands out a short lived address for
#     each part, so no video bytes pass through Render
#   * a part that fails is sent again by itself. When the connection
#     drops the upload waits and carries on when it is back
#   * after a closed tab or a restart, the Upload page lists the
#     unfinished file. Choosing the same file sends only what is missing
#   * Pause, Resume and Cancel upload
#   * the video plays from storage as soon as the upload ends, while
#     transcription runs, and also when a later step fails
#   * storing the file on Shelby is its own step after the upload. It
#     starts by itself, can fail and be tried again, or be done later
#     from the video page. A Shelby outage no longer blocks an upload
#   * the library lists a wallet's videos by who created them, on Shelby
#     or not
#   * limits: 10 GB per file, 5 unfinished uploads per wallet, an
#     unfinished upload is discarded after 7 days
#
#   BACKEND   2 new files, 9 changed. Database migration 004_uploads
#             runs by itself at startup. No new packages.
#   FRONTEND  1 new file, 10 changed. No new packages.
#
#   REQUIRED ONCE, in the Cloudflare dashboard: a CORS policy on the R2
#   bucket that allows PUT from the site's address. Without it the
#   browser cannot send parts. The text to paste is printed at the end.
#
#   ./vm_upload.sh            apply (needs Parts 1c and 2 on the branch)
#   ./vm_upload.sh --force    apply even if local files differ from GitHub
#   ./vm_upload.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_upload"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_upload_backups"

ADD=(
  "backend/src/lib/uploads.ts"
  "backend/src/routes/uploads.ts"
  "frontend/src/lib/uploader.ts"
)
MOD=(
  "backend/.env.example"
  "backend/src/index.ts"
  "backend/src/lib/assets.ts"
  "backend/src/lib/migrations.ts"
  "backend/src/lib/storage.ts"
  "backend/src/lib/store.ts"
  "backend/src/routes/stats.ts"
  "backend/src/routes/videos.ts"
  "backend/src/services/pipeline.ts"
  "frontend/src/app/page.tsx"
  "frontend/src/app/upload/page.tsx"
  "frontend/src/app/v/[id]/page.tsx"
  "frontend/src/app/video/[id]/page.tsx"
  "frontend/src/components/upload/UploadZone.tsx"
  "frontend/src/components/video/OnChainProof.tsx"
  "frontend/src/components/video/ProcessingStatus.tsx"
  "frontend/src/components/video/VideoCard.tsx"
  "frontend/src/components/video/VideoPlayer.tsx"
  "frontend/src/lib/api.ts"
)
