c3MgUmVzdW1lIHRvIHRyeSBhZ2Fpbi4iKTsKICB9Cn0K
B64_A2
verify "$TMPD/a2" "${NEW_ADD[2]}" "frontend/src/lib/uploader.ts"

grep -q "$MARKER" "$TMPD/a0"                       || die "uploads.ts payload missing marker. Aborting."
grep -q "$MARKER" "$TMPD/a2"                       || die "uploader.ts payload missing marker. Aborting."
grep -q '004_uploads' "$TMPD/m3"                 || die "migrations.ts payload missing migration 004. Aborting."
grep -q '003_storage_usage' "$TMPD/m3"           || die "migrations.ts payload lost migration 003. Aborting."
grep -q '/api/uploads' "$TMPD/m1"                || die "index.ts payload does not mount the upload routes. Aborting."
grep -q 'completeMultipart' "$TMPD/m4"           || die "storage.ts payload missing multipart support. Aborting."
grep -q 'checkStorage' "$TMPD/m4"                || die "storage.ts payload lost the startup check. Aborting."
grep -q 'requireAuth' "$TMPD/m7"                 || die "videos.ts payload lost sign in. Aborting."
grep -q 'requireAuth' "$TMPD/a1"                   || die "routes/uploads.ts payload has no sign in check. Aborting."
grep -q 'ResumableUpload' "$TMPD/m13"            || die "UploadZone.tsx payload missing the new upload. Aborting."
grep -q 'useUploadBlobs' "$TMPD/m13"             || die "UploadZone.tsx payload lost the Shelby step. Aborting."
grep -q 'createUpload' "$TMPD/m18"               || die "api.ts payload missing the upload calls. Aborting."
grep -q 'retryVideoJob' "$TMPD/m15"              || die "ProcessingStatus.tsx payload lost the retry. Aborting."
say "22 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied resumable uploads (rebuild Part 3a)."
say "Verify before pushing:"
say "  (cd backend && npx tsc --noEmit) && (cd frontend && npx tsc --noEmit && npm run build)"
say "Undo: ./vm_upload.sh --revert"
cat <<'CORS'

  ONE STEP IN CLOUDFLARE, before the first upload on the preview:
  R2, your bucket, Settings, CORS Policy, Add CORS policy, JSON tab.
  Paste this and save (it can take 30 seconds to take effect):

[
  {
    "AllowedOrigins": [
      "https://videomind-git-rebuild-easyprobeats-projects.vercel.app",
      "http://localhost:3000"
    ],
    "AllowedMethods": ["PUT", "GET", "HEAD"],
    "AllowedHeaders": ["Content-Type"],
    "ExposeHeaders": ["ETag"],
    "MaxAgeSeconds": 3600
  }
]

CORS
